    ok("!! the REPORTED line gives the distances of every step-size network from wip and from its twin, the audit means of all twelve networks in rank order (best first) and the unpenalised gain; the LOST line names every lost run by arm, condition and id and not the autopilot's", (() => { const x = mkAu({ a02_26012: 0.05, s02_26011: -0.03 }); x.dark.a02_26013[7].bad = true; x.lit.s02_26011[3].bad = true; x.dark.autopilot[5].bad = true; x.dark.b02_26011[2].bad = true; const b = X.bottomLines(x); return /distances a02_26011 L1 [\d.]+ from wip, [\d.]+ from its twin; a02_26012 L1/.test(b[12]) && /b02_26014 L1 [\d.]+ from wip, [\d.]+ from its twin; audit means in rank order/.test(b[12]) && b[12].split(/rank order[^;]*?\) /)[1].split(";")[0].split(", ").length === 12 && /the lost runs: s02_26011 lit k3, a02_26013 dark k7, b02_26011 dark k2$/.test(b[7]) && /LOST \(runs lost of 400\): law0 0, c02 0, q02 0, s02_26011 1, s02_26012 0, s02_26013 0, s02_26014 0, a02_26011 0, a02_26012 0, a02_26013 1, a02_26014 0, b02_26011 1,/.test(b[7]); })());
